using Tern.App.Commands;

namespace Tern.App.Help;

public sealed record BeginnerStep(string Title, string Action, string Expected);
public sealed record BeginnerLesson(string Id, string Name, string When, string Why, string Prerequisite,
    string Example, string Result, string Troubleshooting, IReadOnlyList<BeginnerStep> Steps, string? LaunchCommandId = null);

/// <summary>Everyday goals first; instructions never run edits, saves or network requests.</summary>
public static class BeginnerLessons
{
