                "A checklist can be printed as text. Export it as PDF when its page appearance matters.",
                "The Windows print dialog lets you choose a destination. Cancel closes it without changing your note.",
                "If Print is disabled, open a file or write something first and wait for the current operation to finish. If no printer is available, export a PDF and keep it for later. Check the destination before confirming Print.",
                [new("Check the text", "Read the note and correct any mistakes. Save if you want those edits kept.", "The document is ready to print."),
                 new("Open printing", "Choose File → Print…." + Key(CommandIds.Print), "Windows shows its print options; the Markdown file is unchanged."),
                 new("Choose a destination", "Review the printer and options, then choose Print only when correct. Choose Cancel to return without printing.", "Your saved note remains available for further editing.")]),
            new("recover", "Undo a mistake and recover work", "Use this after a wrong edit, a close decision or an interrupted session.",
                "Undo reverses recent edits. Version history and startup recovery offer separate copies to review; they are not the same as reopening a tab.",
                "For Undo, keep the edited note open. Version history needs earlier saves made by Tern. Startup recovery needs an existing checkpoint.",
                "Typed the wrong sentence? Choose Edit → Undo. Need an earlier saved version? Choose File → Version History….",
                "You can compare recovered text before saving it. The current disk file stays separate from a restored unsaved copy.",
                "Save keeps edits; Don't save discards unsaved edits; Cancel keeps the note open. Close tab keeps the saved file. Library × closes associated tabs after save decisions and removes the reference. Remove in Recent only forgets a history entry. Move to Recycle Bin removes the actual file; restore it using Windows Recycle Bin when available. Recovery and history are not a replacement for backups.",
                [new("Undo an edit", "Choose Edit → Undo after a mistake." + Key(CommandIds.Undo) + " Choose Edit → Redo to put the edit back if needed.", "The open text changes; save deliberately if you want that state kept on disk."),
                 new("Review an earlier save", "Choose File → Version History… for a saved note. Select a recorded version, compare it, then open it as a separate unsaved copy when needed.", "The current saved file is kept while you review the older text."),
                 new("Review recovery after an interruption", "If Review recovered work appears on startup, compare the recovered edits with the disk file. Choose Restore as unsaved copy to inspect a separate note, or Ask later if unsure.", "Nothing overwrites the original file automatically. Save a recovered copy to a separate filename after checking it.")]),
            new("practice", "Practise safely with a small note", "Use this to try the main writing tasks without changing your real notes.",
                "A short practice note makes headings, emphasis and checklists easier to recognize. The example is plain text you can select and copy.",
                "No account, workspace or connection is needed. Create a new document for practice.",
                BeginnerPractice.Text,
                "You have tried writing, preview, formatting, Undo and Save using your own practice file.",
                "If the marks show in your finished page, keep the blank lines and spaces in the example. Choose Edit → Undo if a change looks wrong. Closing this guide does not remove your note.",
                [new("Start a practice document", "Choose File → New Document. In this guide's example below, select the text and copy it with Ctrl+C.", "Your real notes stay in their other tabs."),
                 new("Paste and compare", "Choose Split, click the writing pane and paste with Ctrl+V. The left side has # and ** marks; the right side shows a heading and bold text.", "The same words appear as source and as a formatted page."),
                 new("Try one change and Undo", "Select one word and choose Format → Bold, then Edit → Undo. Try Format → Checklist on a short line.", "You can make and reverse formatting changes."),
                 new("Keep your practice", "Choose File → Save and enter practice-note.md in a folder you can find again.", "The practice file can be reopened later.")], CommandIds.NewFile),
            new("organize", "Keep related files in a folder", "Use this when several notes belong to one project.",
                "A folder is a physical directory. Open Folder browses its contents without creating a workspace. A workspace adds a name and persistent project context. Individual notes work without either.", "Have an existing folder of notes, or choose a parent folder for a new project.",
                "Example: a Holiday folder containing plans.md, packing.md and an assets folder for pictures.", "The Library shows your project files. You can keep several project folders open and switch between them.",
                "Open Folder browses an existing directory. Create Workspace makes a named workspace at the chosen location and refuses an existing name. Open Workspace restores a saved context. Close Workspace and Close All Workspaces review unsaved notes; they do not delete folders or files.",
                [new("Open an existing project", "Choose File → Open Folder… and select the folder. For a new empty project, choose File → Create Workspace… instead.", "The Library shows the folder's files."),
                 new("Open another project when needed", "Choose Open Workspace… for another saved context, or Open Folder… for another directory. Select a root in the stacked Library trees.", "Each folder has its own tree. Switching keeps open tabs and unsaved writing."),
                 new("Close a project safely", "Choose File → Close Workspace for the selected folder, or Close All Workspaces for all open folders. Review Save, Don't save and Cancel choices.", "Folders detach after your decisions; standalone and unnamed notes remain separate.")], CommandIds.OpenFolder),
            new("ai-choice", "Work with or without AI", "Use this when deciding whether an AI connection would help your Markdown work.",
                "Without AI, Tern can create and edit notes, format Markdown, search, preview, manage folders and export PDF offline. AI can suggest drafts, rewrites or explanations, but its answers can be wrong. It is optional, not a requirement for writing.",
                "No connection is needed for ordinary editing. Cloud AI needs provider access, an endpoint, a model and sometimes a paid API key. Local Ollama needs a running server and an installed model; it need not use the internet for each question. Performance and privacy depend on the chosen service.",
                "Draft: Write a Markdown meeting agenda with three sections.\n\nRewrite: Make this paragraph shorter without changing its facts: [paste your chosen paragraph].\n\nExplain: Explain why this Markdown table is not aligned: [paste the table].\n\nCheck structure: Suggest clearer headings for this outline; do not invent facts: [paste your outline].",
                "You can choose a saved connection in the main toolbar and update your active note through Alt+Space. Check the result in Split, Undo if needed, and save deliberately. The feature guide answers questions separately without changing notes.",
                "Stay offline if you do not want to share text, pay provider charges or manage a model. Cloud services may charge and receive the text you send; local models use your computer's resources. Check claims and formatting yourself. A saved connection alone does not grant an AI access to your files or workspace.",
                [new("Connect once", "For ordinary writing, use File → New Document and Split. To add AI, choose Edit → Settings → AI connections. Follow Choose service, Configure connection, then Validate and save. Validate connection sends a fixed test message; read its result, then Save connection securely.", "Opening setup sends nothing. Ordinary editing works without AI."),
                 new("Choose your connection", "Use the AI selector on the main screen to choose among saved API, Copilot and MCP connections. API and Copilot use Write with AI; MCP uses Open MCP tools to review a manual tool call. You can switch without reopening Settings.", "The selected connection is remembered for future requests."),
                 new("Describe a change", "Press Alt+Space in Source, preview or the Reference pane. Check the active note named in the panel, enter your request and choose Generate & update note. The note and question are sent to the selected service.", "AI updates the active note as one undoable edit. Cancel stops waiting; it cannot recall text already received by the service."),
                 new("Review your updated draft", "Choose Split to inspect headings, lists, links and facts. Undo restores the previous draft. Choose File → Save when satisfied. Use the feature guide to ask general questions without modifying a note.", "AI changes the open draft only after Generate; it is not automatically saved to disk.")], CommandIds.AIConnections),
            new("ai", "Try optional AI help", "Use this only if you want a separate service to answer a question.",
                "Tern works without AI. Save a connection once, choose it in the main toolbar and use Alt+Space to draft or rewrite the active note. Nothing is sent merely by opening the panel.", "Have access to a supported AI service or a local model. A ChatGPT website subscription alone does not provide an API key.",
                "Example: Turn these Markdown notes into a short checklist, keeping every fact: # Garden plan\nBuy seeds. Water seedlings.\n\nCopy only the text you want the service to receive; do not include private writing by mistake.",
                "The active note is updated in one undoable edit after you choose Generate & update note. Saving to disk remains your choice.",
                "If you do not know your service details, you can close the window and keep writing normally. Ask your provider for API access details, or use a local model you already installed. Cancel can stop waiting, but cannot recall text a service has received.",
                [new("Open Settings once", "Choose Edit → Settings → AI connections, then Manage AI connections. Selecting a saved connection stays on Choose service; choose Configure connection to edit it. Setup guide opens official documentation for the selected service.", "Choose an API, GitHub Copilot or MCP server in the AI service menu. Enter the settings requested for that type; APIs need a name, model and key, while MCP needs a server address. Continue to validation. Validate connection sends a fixed test message and may incur provider usage. Read the result and Save connection securely."),
                 new("Choose a saved service", "Use the main toolbar's AI connection selector. Open a writable note, then press Alt+Space in Source, Reading preview or Reference.", "The larger writing panel puts connection selection first and names the active note and destination. MCP instead opens its manual tool workspace."),
                 new("Generate and review", "Describe your change and choose Generate & update note. Check the updated Markdown, Undo if needed and save when ready. Ask any general question in the guide using Ask question.", "Writing requests update the active note; guide answers do not change documents. Neither action saves a file automatically.")], CommandIds.AIConnections),
        ];
        var writingShortcut = Gesture.Describe(registry.GetGesture(CommandIds.AskAI));
        if (writingShortcut.Length == 0) writingShortcut = "Edit → Write with AI";
        return lessons.Select(lesson => lesson with
        {
            Why = lesson.Why.Replace("Alt+Space", writingShortcut, StringComparison.Ordinal),
            Result = lesson.Result.Replace("Alt+Space", writingShortcut, StringComparison.Ordinal),
            Steps = lesson.Steps.Select(step => step with { Action = step.Action.Replace("Alt+Space", writingShortcut, StringComparison.Ordinal) }).ToArray(),
        }).ToArray();
    }
}
